def make_out(vin,outv,fill,conn=True):
    # find a connected component of color c whose interior ints include fill as rare/mode/etc, 
    # bbox crop with border==fill == outv
    for c in set(v for row in vin for v in row):
        for conn_test in [conn]:
            comps=flood(vin,c,conn_test)
            for cells in comps:
                hmn=min(r for r,_ in cells); hmx=max(r for r,_ in cells)
                vmn=min(c for _,c in cells); wmx=max(c for _,c in cells)
                b=hmx-hmn+1;a=wmx-vmn+1
                # interior colors
                inner_cells=[(r,cv) for r in range(hmn+1,hmx) for cv in range(vmn+1,wmx)]
                ints=[vin[r][cv] for r,cv in inner_cells]
                if len(ints)==0 or b<2 or a<2: continue
                cnt=Counter(ints)
                reg=[[vin[r][cv] for cv in range(vmn,wmx+1)] for r in range(hmn,hmx+1)]
                cand=[row[:] for row in reg]
                for rr in range(b):
                    for cc in range(a):
                        if rr==0 or rr==b-1 or cc==0 or cc==a-1:
                            cand[rr][cc]=fill
                if cand==outv:
                    return {'color':c,'bbox':(b,a),'ints':dict(cnt)}
    return None

